insert into academy_lessons (section_id, sort, title, scenes) select (select id from academy_sections where slug = 'marketplace-with-claude'), 1, 'Your own listings, never the same ad twice', '[{"caption":"Sales > Marketing","say":"Your Marketing tab is the Facebook Marketplace tool for your own profile: what to post today, the kit for each car, the replies and your log.","visual":{"kind":"title","heading":"Sales > Marketing","text":"Your own profile, your own listings"}},{"caption":"A copy variant of your own","say":"Each car can have up to five live listings across the team, the owner''s included. Each listing is a different copy variant: its own title, description wording, photo order and cover photo.","visual":{"kind":"list","heading":"Your variant","items":["Its own title","Its own description wording","Its own photo order and cover","Claimed by you alone"]}},{"caption":"Claim, post, log","say":"Press Claim on a Today item, open its kit, post it on Facebook, then press Posted and paste the listing''s address. A claim you do not post within a day lets go by itself.","visual":{"kind":"steps","heading":"One car","items":["Claim the variant","Open the kit, download the photos","Post it on Facebook","Posted: paste the address"]}},{"caption":"The words","say":"Nothing a buyer reads says rent, rental or for rent. Every listing keeps the line: Daily and weekly bookings only, not for sale. The price is for one day.","visual":{"kind":"rule","heading":"The wording rule","text":"Never \"rent\" or \"rental\". Always \"Daily and weekly bookings only, not for sale\".","tone":"warn"}}]'::jsonb where not exists (select 1 from academy_lessons where section_id = (select id from academy_sections where slug = 'marketplace-with-claude') and sort = 1);
insert into academy_lessons (section_id, sort, title, scenes) select (select id from academy_sections where slug = 'marketplace-with-claude'), 2, 'Claude in your own Chrome', '[{"caption":"Paste the instructions","say":"Your Marketing tab has the instructions for Claude. Sign in to Facebook and to CarmaCars yourself, paste them into Claude in your Chrome, and say: run my Marketplace session.","visual":{"kind":"steps","heading":"Start a session","items":["Sign in to Facebook and CarmaCars yourself","Copy the instructions from Marketing","Paste them into Claude","Run my Marketplace session"]}},{"caption":"Claude stops at any check","say":"Claude never types a password and never gets past a Facebook check. On a security check, a CAPTCHA or a confirm it''s you screen, it stops and tells you.","visual":{"kind":"rule","heading":"Stop and hand over","text":"Security check, CAPTCHA, removed listing, request for ID: Claude stops and tells you.","tone":"warn"}},{"caption":"Templates only","say":"Claude answers the inbox with the kit''s replies only. A discount, a cash deal, an angry message or a question the templates do not answer gets the send your number reply, and you take it from there.","visual":{"kind":"chat","lines":[{"who":"buyer","text":"Can you do $50 a day cash?"},{"who":"claude","text":"Easiest by phone. Send your number and one of our team will call you in a few minutes."}]}},{"caption":"Every post is logged","say":"Claude logs every post, renewal, price update and take-down in your Marketing tab right after doing it, and the inbox session at the end, with every number collected. The numbers are leads credited to you.","visual":{"kind":"title","heading":"Log everything","text":"Your Marketing tab, right away"}}]'::jsonb where not exists (select 1 from academy_lessons where section_id = (select id from academy_sections where slug = 'marketplace-with-claude') and sort = 2);
